WITH lines AS (SELECT id, customer_id, coupon_codes, key, value FROM carts LATERAL VIEW EXPLODE(attributes) x AS key, value), lines_carts AS (SELECT id, customer_id, key, EXPLODE_OUTER(coupon_codes) AS tag FROM lines), base AS (SELECT *, LENGTH(tag) AS tag_length FROM lines_carts WHERE tag IS NOT NULL), enriched AS (SELECT customer_id, key, tag, tag_length, DENSE_RANK() OVER (PARTITION BY tag, key ORDER BY tag_length DESC NULLS FIRST) AS tag_length_dense_rank, DENSE_RANK() OVER w_recent AS tag_length_dense_rank_2, SUM(tag_length) OVER (PARTITION BY customer_id) AS customer_id_sum_tag_length FROM base WINDOW w_recent AS (PARTITION BY key, customer_id ORDER BY tag_length DESC NULLS LAST)), cleaned AS (SELECT *, UPPER(tag) AS tag_upper, COALESCE(key, 'NONE') AS key_filled FROM enriched WHERE tag_length_dense_rank BETWEEN 3 AND 5), enriched_carts AS (SELECT *, ROUND(tag_length_dense_rank_2 / SUM(tag_length_dense_rank_2) OVER (PARTITION BY customer_id), 4) AS tag_length_dense_rank_2_share FROM cleaned WHERE tag IN ('WELCOME5', 'SPRING10', 'VIP')), enriched_carts_2 AS (SELECT src.*, p.credit_limit, p.age, p.segment FROM enriched_carts src LEFT JOIN customers p ON src.customer_id = p.id) SELECT s.customer_id, s.tag_length_dense_rank, s.tag_length_dense_rank_2, s.customer_id_sum_tag_length, s.tag_upper, s.key_filled, s.tag_length_dense_rank_2_share, s.age, s.segment, CASE WHEN segment RLIKE '^(Corporate|SMB)$' THEN 'OTHER_ZONE' WHEN segment RLIKE '^(Consumer)$' THEN 'EXTENDED' ELSE 'GROUP_B' END AS segment_zone, (SELECT AVG(x.shipping_fee) FROM orders x WHERE x.customer_id = s.customer_id) AS avg_order_shipping_fee FROM enriched_carts_2 s ORDER BY tag_length_dense_rank_2_share DESC NULLS FIRST
